describe("doctests of sympy.series.series", () => {
  it("series(f, x, 2, 6, \"+\")", () => {
    const x = new Sym('x');
    expect(sympyStr(series(fn('tan', [x], { evaluate: false }), x, Rational.of(2n, 1n, { gcd: 1n }), 6, '+', {}))).toBe('tan(2) + (1 + tan(2)**2)*(x - 2) + (x - 2)**2*(tan(2)**3 + tan(2)) + (x - 2)**3*(1/3 + 4*tan(2)**2/3 + tan(2)**4) + (x - 2)**4*(tan(2)**5 + 5*tan(2)**3/3 + 2*tan(2)/3) + (x - 2)**5*(2/15 + 17*tan(2)**2/15 + 2*tan(2)**4 + tan(2)**6) + O((x - 2)**6, (x, 2))');
  });
  it("series(f, x, 2, 3, \"-\")", () => {
    const x = new Sym('x');
    expect(sympyStr(series(fn('tan', [x], { evaluate: false }), x, Rational.of(2n, 1n, { gcd: 1n }), 3, '-', {}))).toBe('tan(2) + (2 - x)*(-tan(2)**2 - 1) + (2 - x)**2*(tan(2)**3 + tan(2)) + O((x - 2)**3, (x, 2))');
  });
});

